#!/usr/bin/env bash\nset -e\n\n# Helper to assert expected exit code\nassert_exit_code() {\n  local expected=$1\n  local actual=$2\n  if [ "$expected" -ne "$actual" ]; then\n    echo "Expected exit code $expected but got $actual"\n    exit 1\n  fi\n}\n\n# Create a temporary workspace\nWORKDIR=$(mktemp -d)\nexport GITHUB_WORKSPACE="$WORKDIR"\n\n# Copy action source files into the temp workspace\nmkdir -p "$WORKDIR/src"\ncp "$(dirname \"$0\")/../src/index.js" "$WORKDIR/src/index.js"\ncp "$(dirname \"$0\")/../action.yml" "$WORKDIR/action.yml"\n\n# Test 1: No TODOs present – should succeed\necho "console.log('Hello world');" > "$WORKDIR/clean.js"\nnode "$WORKDIR/src/index.js"\nassert_exit_code 0 $?\n\n# Test 2: TODO present – should fail\necho "// TODO: fix this later" > "$WORKDIR/bad.js"\nnode "$WORKDIR/src/index.js"\nCODE=$?\nif [ "$CODE" -eq 0 ]; then\n  echo "Expected failure due to TODO but succeeded"\n  exit 1\nfi\n\necho "All tests passed."\n
